import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.PlanningGraphDomain;

/**
 * Bounded, bag-preserving UNION choices in the existing semantic groups. Distribution visits only original JOIN rows;
 * factoring offers the maximal common multiset of statement patterns in each original binary UNION. Generated children
 * remain ordinary costed groups, but do not recursively expand into a UNION normal form.
 */
@PackedHotPath
final class PackedUnionAlternatives {

	private static final int MAX_FACTORS = 64;
	private static final byte SAFE = 1;
	private static final byte APPLIED = 2;
	private static final int[] NO_CHILDREN = new int[0];

	private final PackedExpressionInterner relations;
	private final PackedExpressionInterner payloads;
	private final PackedNodeMetadataArena metadata;
	private final PackedAlternativeSink sink;
	private final int[] binary = new int[2];
	private int originalRelationCount;
	private byte[] eligibility;
	private int[] leftFactors;
	private int[] rightFactors;
	private int[] factorStack;
	private boolean[] leftCommon;
	private boolean[] rightCommon;
	private int[] patternKeys;
	private int[] patternCounts;

	PackedUnionAlternatives(PackedExpressionInterner relations, PackedExpressionInterner payloads,
			PackedNodeMetadataArena metadata,
			PackedAlternativeSink sink) {
		this.relations = relations;
		this.payloads = payloads;
		this.metadata = metadata;
		this.sink = sink;
	}

	/** Called with the complete source row count before logical saturation starts. */
	void setOriginalRelationCount(int count) {
		if (count <= 0 || count > relations.size()
				|| originalRelationCount != 0 && originalRelationCount != count) {
			throw new IllegalArgumentException("UNION source row boundary must be established once");
		}
		originalRelationCount = count;
	}

	void apply(int expressionId) {
		if (expressionId <= 0 || expressionId > originalRelationCount) {
			return;
		}
		ensureEligibility();
		if (eligibility[expressionId] != SAFE) {
			return;
		}
		eligibility[expressionId] |= APPLIED;
		switch (relations.operatorTag(expressionId)) {
		case PackedRelOp.JOIN -> {
			addDistribution(expressionId, 0);
			addDistribution(expressionId, 1);
		}
		case PackedRelOp.UNION -> addCommonBgpFactorization(expressionId);
		default -> {
		}
		}
	}

	/**
	 * The source interner is topological: children are permanent group seeds preceding their parent. One linear pass
	 * audits a pure relational fragment without recursively revisiting shared subtrees. Lexical UNION/branch markers
	 * are harmless here: these operators forward input mappings, and the whitelist contains no scalar observations,
	 * ordinary writes, independent projections, or remote operators that can observe the changed lexical boundary.
	 */
	private void ensureEligibility() {
		if (eligibility != null) {
			return;
		}
		eligibility = new byte[originalRelationCount + 1];
		for (int id = 1; id <= originalRelationCount; id++) {
			if (!pureLocation(id)) {
				continue;
			}
			boolean safe = switch (relations.operatorTag(id)) {
			case PackedRelOp.STATEMENT_PATTERN -> relations.childCount(id) == 0 && relationalPattern(id);
			case PackedRelOp.BINDING_SET_ASSIGNMENT, PackedRelOp.SINGLETON_SET, PackedRelOp.EMPTY_SET ->
				relations.childCount(id) == 0;
			case PackedRelOp.JOIN, PackedRelOp.UNION -> relations.payloadId(id) == 0
					&& relations.childCount(id) == 2
					&& safeChild(id, 0) && safeChild(id, 1);
			default -> false;
			};
			if (safe) {
				eligibility[id] = SAFE;
			}
		}
	}

	private boolean relationalPattern(int id) {
		int payload = relations.payloadId(id);
		for (int ordinal = 0; ordinal < payloads.childCount(payload); ordinal++) {
			int term = payloads.childGroupId(payload, ordinal);
			if (term == 0) {
				continue;
			}
			int value = payloads.semanticScopeId(term);
			int flags = payloads.executionDomainId(term);
			if (PackedTermBindings.observesInput(PackedRelOp.STATEMENT_PATTERN, value, flags)
					&& !PackedTermBindings.possibleOutput(PackedRelOp.STATEMENT_PATTERN, ordinal, value, flags)) {
				// An unvalued constant reads its name from the incoming frame without exporting that binding.
				// Factoring must not move a producer of that name ahead of the observation.
				return false;
			}
		}
		return true;
	}

	private boolean pureLocation(int id) {
		return (PackedNodeMetadataArena.structuralScopeFlags(relations.semanticScopeId(id))
				& ~PackedNodeMetadataArena.VARIABLE_SCOPE_CHANGE) == 0
				&& relations.executionDomainId(id) == 0
				&& relations.occurrenceId(id) == 0
				&& metadata.relationReplaySafety(id) == 2
				&& metadata.relationRequiredInputNames(id) == 0
				&& metadata.relationProtectedInputNames(id) == 0
				&& metadata.relationNullableInputNames(id) == 0
				&& metadata.relationOrdinaryWriteNames(id) == 0
				&& metadata.relationIndependentOutputNames(id) == 0
				&& metadata.relationGraphDomain(id).kind() != PlanningGraphDomain.Kind.UNKNOWN;
	}

	private boolean safeChild(int parentId, int ordinal) {
		int childId = relations.childGroupId(parentId, ordinal);
		return childId < parentId && (eligibility[childId] & SAFE) != 0
				&& relations.graphDomainId(parentId) == relations.graphDomainId(childId)
				&& metadata.relationGraphDomain(parentId).equals(metadata.relationGraphDomain(childId));
	}

	private void addDistribution(int joinId, int unionOrdinal) {
		int unionId = relations.childGroupId(joinId, unionOrdinal);
		if (relations.operatorTag(unionId) != PackedRelOp.UNION) {
			return;
		}
		int otherId = relations.childGroupId(joinId, 1 - unionOrdinal);
		int leftArm = relations.childGroupId(unionId, 0);
		int rightArm = relations.childGroupId(unionId, 1);
		int leftJoin = unionOrdinal == 0 ? canonicalBinary(PackedRelOp.JOIN, leftArm, otherId, joinId)
				: canonicalBinary(PackedRelOp.JOIN, otherId, leftArm, joinId);
		int rightJoin = unionOrdinal == 0 ? canonicalBinary(PackedRelOp.JOIN, rightArm, otherId, joinId)
				: canonicalBinary(PackedRelOp.JOIN, otherId, rightArm, joinId);
		addBinaryAlternative(joinId, PackedRelOp.UNION, leftJoin, rightJoin,
				PackedRuleProofs.UNION_JOIN_DISTRIBUTION);
	}

	private void addCommonBgpFactorization(int unionId) {
		ensureFactorScratch();
		int leftCount = collectFactors(relations.childGroupId(unionId, 0), leftFactors);
		int rightCount = collectFactors(relations.childGroupId(unionId, 1), rightFactors);
		if (leftCount < 0 || rightCount < 0) {
			return;
		}
		Arrays.fill(leftCommon, 0, leftCount, false);
		Arrays.fill(rightCommon, 0, rightCount, false);
		Arrays.fill(patternKeys, 0);
		Arrays.fill(patternCounts, 0);
		for (int index = 0; index < rightCount; index++) {
			int id = rightFactors[index];
			if (relations.operatorTag(id) == PackedRelOp.STATEMENT_PATTERN) {
				int payload = relations.payloadId(id);
				int slot = patternCountSlot(payload);
				patternKeys[slot] = payload;
				patternCounts[slot]++;
			}
		}

		int commonCount = 0;
		for (int index = 0; index < leftCount; index++) {
			int id = leftFactors[index];
			if (relations.operatorTag(id) == PackedRelOp.STATEMENT_PATTERN) {
				// The payload includes every term, scan option and native statement semantic coordinate. The
				// eligibility proof already equates graph/execution domains and permits only lexical scope flags.
				int payload = relations.payloadId(id);
				int slot = patternCountSlot(payload);
				int remaining = patternCounts[slot];
				if (remaining > 0) {
					leftCommon[index] = true;
					commonCount++;
					patternCounts[slot] = remaining - 1;
				}
			}
		}
		if (commonCount == 0) {
			return;
		}
		for (int index = 0; index < rightCount; index++) {
			int id = rightFactors[index];
			if (relations.operatorTag(id) == PackedRelOp.STATEMENT_PATTERN) {
				int payload = relations.payloadId(id);
				int slot = patternCountSlot(payload);
				int remaining = patternCounts[slot];
				if (remaining == 0) {
					rightCommon[index] = true;
				} else {
					patternCounts[slot] = remaining - 1;
				}
			}
		}

		int common = conjunction(leftFactors, leftCommon, leftCount, true, unionId);
		int left = conjunction(leftFactors, leftCommon, leftCount, false, unionId);
		int right = conjunction(rightFactors, rightCommon, rightCount, false, unionId);
		// In particular, A UNION A becomes A JOIN (unit UNION unit), preserving two copies of every A row.
		int remainder = canonicalBinary(PackedRelOp.UNION, left, right, unionId);
		addBinaryAlternative(unionId, PackedRelOp.JOIN, common, remainder,
				PackedRuleProofs.UNION_COMMON_BGP_FACTOR);
	}

	private void ensureFactorScratch() {
		if (leftFactors != null) {
			return;
		}
		leftFactors = new int[MAX_FACTORS];
		rightFactors = new int[MAX_FACTORS];
		factorStack = new int[MAX_FACTORS];
		leftCommon = new boolean[MAX_FACTORS];
		rightCommon = new boolean[MAX_FACTORS];
		patternKeys = new int[MAX_FACTORS * 2];
		patternCounts = new int[MAX_FACTORS * 2];
	}

	/** At most MAX_FACTORS nonzero payload IDs occupy this fixed, half-full primitive multiset table. */
	private int patternCountSlot(int payload) {
		int mask = patternKeys.length - 1;
		int slot = (int) PackedPrimitiveHash.finish(payload) & mask;
		while (patternKeys[slot] != 0 && patternKeys[slot] != payload) {
			slot = slot + 1 & mask;
		}
		return slot;
	}

	/** A bounded traversal counts repeated DAG occurrences, never a set of factor IDs. */
	private int collectFactors(int expressionId, int[] factors) {
		int pending = 1;
		int count = 0;
		factorStack[0] = expressionId;
		while (pending != 0) {
			int id = factorStack[--pending];
			if (relations.operatorTag(id) == PackedRelOp.JOIN) {
				if (pending + 2 > factorStack.length) {
					return -1;
				}
				factorStack[pending++] = relations.childGroupId(id, 1);
				factorStack[pending++] = relations.childGroupId(id, 0);
			} else {
				if (count == factors.length) {
					return -1;
				}
				factors[count++] = id;
			}
		}
		return count;
	}

	private int conjunction(int[] factors, boolean[] common, int count, boolean selectCommon, int sourceId) {
		int result = 0;
		for (int index = 0; index < count; index++) {
			if (common[index] == selectCommon) {
				result = result == 0 ? factors[index]
						: canonicalBinary(PackedRelOp.JOIN, result, factors[index], sourceId);
			}
		}
		return result == 0 ? canonical(PackedRelOp.SINGLETON_SET, NO_CHILDREN, 0, sourceId) : result;
	}

	private int canonicalBinary(int operator, int leftId, int rightId, int sourceId) {
		binary[0] = relations.groupId(leftId);
		binary[1] = relations.groupId(rightId);
		return canonical(operator, binary, 2, sourceId);
	}

	private int canonical(int operator, int[] children, int count, int sourceId) {
		int before = relations.size();
		int result = relations.internCanonical(operator, 0, 0, 0, 0,
				relations.graphDomainId(sourceId), children, 0, count);
		if (result > before) {
			// This is a different subtree, not another estimate of its source. Do not copy the source cardinality,
			// input contract or implementation hints; all admitted children have empty observation/write contracts.
			metadata.attachRelation(result, 0, 0, Double.NaN, Double.NaN, 0);
			metadata.attachRelationInputContract(result, 0, 0, 0, 0, 0);
			metadata.attachRelationReplaySafety(result, true);
			metadata.attachRelationGraphDomain(result, metadata.relationGraphDomain(sourceId));
			int first = 0;
			int last = 0;
			for (int index = 0; index < count; index++) {
				int childFirst = metadata.relationSourceFirst(children[index]);
				if (childFirst != 0) {
					first = first == 0 ? childFirst : Math.min(first, childFirst);
				}
				last = Math.max(last, metadata.relationSourceLast(children[index]));
			}
			metadata.attachRelationSourceOrder(result, first, last);
		}
		return result;
	}

	private void addBinaryAlternative(int sourceId, int operator, int leftId, int rightId, long proof) {
		binary[0] = relations.groupId(leftId);
		binary[1] = relations.groupId(rightId);
		int alternative = sink.addAlternative(sourceId, operator, 0, binary, 2);
		sink.addRuleMask(alternative, proof);
	}
}
